contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 minSum, uint256 depositAmount, uint256 collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        require(collectAmount <= depositAmount);
        require(minSum <= depositAmount);

        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 balanceBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractBalanceBefore = address(c).balance;
        uint256 callerBalanceBefore = address(this).balance;

        bool collectReverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { collectReverted = true; } else { collectReverted = false; }

        uint256 balanceAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractBalanceAfter = address(c).balance;
        uint256 callerBalanceAfter = address(this).balance;

        assert(
            (collectReverted && balanceAfter == balanceBefore && contractBalanceAfter == contractBalanceBefore && callerBalanceAfter == callerBalanceBefore)
            || (!collectReverted && balanceAfter == balanceBefore - collectAmount && contractBalanceAfter == contractBalanceBefore - collectAmount && callerBalanceAfter == callerBalanceBefore + collectAmount)
        );
    }

    receive() external payable {}
}

