pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 minSum, uint256 depositAmount, uint256 collectAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(collectAmount <= depositAmount);
        vm.assume(minSum <= depositAmount);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 balanceBefore;
        try c.balances(address(this)) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        uint256 contractBalanceBefore = address(c).balance;
        uint256 callerBalanceBefore = address(this).balance;
        bool collectReverted;
        try c.Collect(collectAmount) { collectReverted = false; } catch { collectReverted = true; }
        uint256 balanceAfter;
        try c.balances(address(this)) returns (uint256 __r) { balanceAfter = __r; } catch { return; }
        uint256 contractBalanceAfter = address(c).balance;
        uint256 callerBalanceAfter = address(this).balance;
        assertTrue((collectReverted && balanceAfter == balanceBefore && contractBalanceAfter == contractBalanceBefore && callerBalanceAfter == callerBalanceBefore)
            || (!collectReverted && balanceAfter == balanceBefore - collectAmount && contractBalanceAfter == contractBalanceBefore - collectAmount && callerBalanceAfter == callerBalanceBefore + collectAmount));
    }

    function testFuzz_run(uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        _run(minSum, depositAmount, collectAmount);
    }

    receive() external payable {}
}
